// Generate src/api/types.ts from the committed src/api/openapi.json.
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const source = new URL('../src/api/openapi.json', import.meta.url);
const target = new URL('../src/api/types.ts', import.meta.url);

const header =
  '// Generated by scripts/gen-api-types.mjs from openapi.json. Do not edit.\n' +
  '// Regenerate with: npm run gen:api\n\n';

const ast = await openapiTS(source);
await writeFile(target, header + astToString(ast));
console.log(`Wrote ${fileURLToPath(target)}`);
